// TH14 v1.00b Stage 6 道中 第4波（st06.ecl.txt:697-715 MainSub04 入口）。
// 左排程=MainSub04（本任务内同步循环），右排程=MainSub04b（async，独立任务 717-737）。
// 敌=Phantom02（1069-1092），射击=Phantom02_at（1094-1132）。
// 弹型源 etSprite(18,6) -> TH14_BIG_BALL（transcribe/th14/touhou-bullets.ecl）。

const TH14_BIG_BALL: int = 640;

const TIME_LIMIT: int = 2424;    // 120 开场缓冲 + 2300 排程/尾弹估计 + 4 启动余量
const OPENING_BUFFER: int = 120;

// 原 Phantom02_at：配置一次（含一次 %RANDRAD）后每 40 帧重复 etOn。
async sub phantom_fire() {
    var alpha: int = rand(65536);           // 原 etAngle(0, %RANDRAD, π/4)，每敌一次、各轮共用
    var ways: int = 8;                       // 原 etCount：!E 4 / 其余 8
    var spd: fx = 5fx;                       // 原 etSpeed：E2.8 N4.0 H4.5 L5.0
    var volleys: int = 7;                    // 原 diffI($A,3,3,5,7)
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY { ways = 4; spd = 2.8fx; volleys = 3; }
    if rank == RANK_NORMAL { spd = 4.0fx; volleys = 3; }
    if rank == RANK_HARD { spd = 4.5fx; volleys = 5; }
    wait(20);                                // 原 wait(20) 后进入 etOn 循环
    for k in 0..volleys {
        for i in 0..ways {
            var a: int = alpha + (i * 65536) / ways;   // 原 mode3 固定方向整周环
            // 原 etEx(0,0,2,1,·,·,·) type2 ANIM 进入：position -= 4 * velocity
            var bx: fx = $self_x - (4fx * spd) * cos(a as angle);
            var by: fx = $self_y - (4fx * spd) * sin(a as angle);
            _ = fire(TH14_BIG_BALL, 6, bx, by, spd, a as angle, none, none);
        }
        wait(40);
    }
}

// 原 Phantom02：REL 圆周（r 0→32、ω=2°/帧），160 帧后叠 ABS 自机方向缓慢加速漂移。
async sub phantom() {
    set_invuln(65535);
    set_hurtbox(14fx);                       // 原 setHurtbox(28,28)：第一值×0.5
    set_hitbox(8fx);                         // 原 setHitbox(16,16)：第一值×0.5
    var x0: fx = $self_x;
    var y0: fx = $self_y;
    var theta: angle = rand(65536) as angle;  // 原 moveCircleRel(%RANDRAD, 0.034906585, 0, 0)
    spawn phantom_fire();                      // 原 @Phantom02_at() async
    var ox: fx = 0fx;                          // ABS 漂移累计位移
    var oy: fx = 0fx;
    var aim: angle = 0deg;                     // 原 moveVel(%ANGLE_PLAYER, 0)
    var t: int = 0;
    loop {
        var r: fx = 32fx;                      // 原 moveCircleRelTime(80,0,-999999,32,0)
        if t < 80 { r = 32fx * (t as fx) / 80fx; }
        if t >= 160 {                           // 原两次 wait(80) 后 moveVel + moveSpeedTime(120,0,1)
            if t == 160 { aim = aim_player(); }
            var spd: fx = ((t - 160) as fx) / 120fx;
            if spd > 1fx { spd = 1fx; }
            ox = ox + spd * cos(aim);
            oy = oy + spd * sin(aim);
        }
        move_to(0, x0 + ox + r * cos(theta), y0 + oy + r * sin(theta), EASE_LINEAR);
        theta = theta + 2deg;                  // 原 ω=0.034906585 rad/帧
        t = t + 1;
        wait(1);
    }
}

sub cast_phantom(side: int) {
    // 原 enmCreate("Phantom02", ±128±RANDF*32, 96+RANDF*64, 100, 1000, 1)
    var ux: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
    var uy: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;
    _ = spawn_enemy((side as fx) * (128fx + ux * 32fx), 96fx + uy * 64fx,
                    100, 0, 0, 0, phantom);
}

// 原 MainSub04b：6 组，每组先 wait(120)，再 4 只、间隔 30。
async sub pattern_right() {
    for g in 0..6 {
        wait(120);
        for j in 0..4 {
            cast_phantom(1);
            wait(30);
        }
    }
}

// 原 MainSub04：先起 async，再 6 组；组内 4 只×wait(30)，组间 wait(120)。
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn pattern_right();                   // 原 @MainSub04b() async（次帧首跑）
    for g in 0..6 {
        for j in 0..4 {
            cast_phantom(-1);
            wait(30);
        }
        wait(120);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
